// https://html.spec.whatwg.org/multipage/named-characters.html#named-character-references
// generated by build.rs from entities.json: (name without the leading "&", characters),
// sorted by the bytes of the name.
include!(concat!(env!("OUT_DIR"), "/named_character_references.rs"));

/// Finds the longest name in the table that prefixes a sequence of characters fed one at
/// a time, narrowing a range of the sorted table on each character.
pub(crate) struct NameMatcher {
    lo: usize,
    hi: usize,
    depth: usize,
    longest: Option<(usize, &'static str)>,
}

impl NameMatcher {
    pub(crate) fn new() -> Self {
        NameMatcher {
            lo: 0,
            hi: NAMED_CHARACTER_REFERENCES.len(),
            depth: 0,
            longest: None,
        }
    }

    /// Feeds the next character. Returns false once no name starts with the characters
    /// fed so far, after which the longest match can't change.
    pub(crate) fn push(&mut self, c: char) -> bool {
        let Ok(b) = u8::try_from(c) else {
            self.lo = self.hi;
            return false;
        };
        let d = self.depth;
        // every name in lo..hi shares the first d bytes, so the range is sorted by byte d,
        // with names of length d first.
        let range = &NAMED_CHARACTER_REFERENCES[self.lo..self.hi];
        let start = range.partition_point(|(n, _)| n.len() <= d || n.as_bytes()[d] < b);
        let end = range.partition_point(|(n, _)| n.len() <= d || n.as_bytes()[d] <= b);
        self.hi = self.lo + end;
        self.lo += start;
        self.depth += 1;
        if self.lo < self.hi {
            let (name, value) = NAMED_CHARACTER_REFERENCES[self.lo];
            if name.len() == self.depth {
                self.longest = Some((self.depth, value));
            }
            true
        } else {
            false
        }
    }

    /// The length in characters of the longest match and its replacement characters.
    pub(crate) fn longest(&self) -> Option<(usize, &'static str)> {
        self.longest
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn longest(input: &str) -> Option<(usize, &'static str)> {
        let mut m = NameMatcher::new();
        for c in input.chars() {
            if !m.push(c) {
                break;
            }
        }
        m.longest()
    }

    #[test]
    fn table_is_sorted_and_complete() {
        assert_eq!(NAMED_CHARACTER_REFERENCES.len(), 2231);
        assert!(
            NAMED_CHARACTER_REFERENCES
                .windows(2)
                .all(|w| w[0].0.as_bytes() < w[1].0.as_bytes())
        );
    }

    #[test]
    fn longest_match() {
        assert_eq!(longest("notit;"), Some((3, "\u{AC}")));
        assert_eq!(longest("notin;"), Some((6, "\u{2209}")));
        assert_eq!(longest("amp"), Some((3, "&")));
        assert_eq!(longest("amp;x"), Some((4, "&")));
        assert_eq!(longest("NotEqualTilde;"), Some((14, "\u{2242}\u{338}")));
        assert_eq!(longest("xyz"), None);
        assert_eq!(longest("am\u{E9}"), None);
    }
}
